import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"YqlossClientHarmony","description":"","frontmatter":{"title":"YqlossClientHarmony","order":3},"headers":[],"relativePath":"zh/mods/yqlossclientharmony.md","filePath":"zh/mods/yqlossclientharmony.md","lastUpdated":1786943111000}'),l={name:"zh/mods/yqlossclientharmony.md"};function s(n,e,i,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="yqlossclientharmony" tabindex="-1">YqlossClientHarmony <a class="header-anchor" href="#yqlossclientharmony" aria-label="Permalink to &quot;YqlossClientHarmony&quot;">​</a></h1><blockquote><p>开源 ADOFAI 修复、特效去除、回放 Mod。</p><p>项目地址：<a href="https://github.com/adofaiex/YqlossClientHarmony" target="_blank" rel="noreferrer">https://github.com/adofaiex/YqlossClientHarmony</a></p></blockquote><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h2><ul><li>修复致命装饰物在 no fail 模式下导致失败的问题</li><li>修复 Set Input 事件导致关卡无法游玩</li><li>修复保存的 <code>.adofai</code> 文件 JSON 格式错误</li><li>防止误退出游戏</li><li>游戏结束播放音效</li><li><strong>特效去除</strong>（Effect Remover）</li><li><strong>回放</strong>（Replay）</li></ul><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ol><li>安装 <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a></li><li>在 <a href="https://github.com/adofaiex/YqlossClientHarmony/releases" target="_blank" rel="noreferrer">Releases</a> 下载最新构建</li><li>通过 UMM 安装，或解压到 <code>A Dance of Fire and Ice/Mods/YqlossClientHarmony/</code></li><li>启动游戏，UMM 设置（默认 <code>Ctrl+F10</code>）中启用相应功能</li></ol><h2 id="教程-录制回放" tabindex="-1">教程：录制回放 <a class="header-anchor" href="#教程-录制回放" aria-label="Permalink to &quot;教程：录制回放&quot;">​</a></h2><ol><li>在 YCH 设置中启用 <strong>YCH</strong> 与 <strong>Replay</strong>（录制）</li><li>游玩关卡，回放将被录制</li></ol><h2 id="教程-播放回放" tabindex="-1">教程：播放回放 <a class="header-anchor" href="#教程-播放回放" aria-label="Permalink to &quot;教程：播放回放&quot;">​</a></h2><ol><li>在 YCH 设置中启用 <strong>YCH</strong> 与 <strong>Replay</strong></li><li>在关卡编辑器中打开关卡，点击 <strong>Load Replay</strong>，选择回放文件（<code>.ychreplay.gz</code> 或 <code>.ychreplaygz</code>）</li><li>将游戏设置调整为与录制者一致（<strong>Async Input 除外</strong>）</li><li>点击 <strong>Jump to Start</strong>，开始游玩</li></ol><h2 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to &quot;疑难解答&quot;">​</a></h2><p><strong>「!!!」出现在 Mod 名称旁？</strong></p><p>你下载的可能是从源码直接构建的版本。请从 <a href="https://github.com/adofaiex/YqlossClientHarmony/releases" target="_blank" rel="noreferrer">Releases</a> 下载正式发布版。</p><p><strong>回放时星球与地板不同步？</strong></p><p>回放时请<strong>关闭 KeyboardChatterBlocker</strong>。</p><p><strong>KeyboardChatterBlocker 与回放录制器不兼容？</strong></p><p>只有部分版本兼容，官方测试过的为 <strong>0.0.10</strong>（0.0.7 不兼容）。</p><p><strong>DLC 支持情况？</strong></p><p>目前对 DLC 支持不完善，如有相关问题可在仓库 Issues 反馈。</p>',19)])])}const m=o(l,[["render",s]]);export{g as __pageData,m as default};
